#include <iostream>


using namespace std;


int digitSum(long long n){int r=0;while(n){r+=n%10;n/=10;}return r;}


int main(){long long n;cin>>n;long long x=n;int sum=0,count=0;


for(long long d=2;d*d<=x;d++){while(x%d==0){sum+=digitSum(d);x/=d;count++;}}


if(x>1){sum+=digitSum(x);count++;}


cout<<(count>=2&&sum==digitSum(n)?"Yes":"No")<<'\n';}
